window.WPR_LOES = Object.assign(window.WPR_LOES || {}, {"W-6": {"k": "Nein, nur 15.700 €", "w": ["Ziff. 18 ist eine vorformulierte Vertragsbedingung → AGB (§ 305 I); durch Unterschrift einbezogen (§ 305 II).", "Inhaltskontrolle, zuerst § 309 (Verbraucher): Nr. 1 verbietet Preiserhöhungen für Waren, die innerhalb von 4 Monaten nach Vertragsschluss geliefert werden sollen.", "Die Klausel greift schon ab 3 Monaten, erfasst also auch Lieferungen im 4. Monat → verbotener Bereich. Keine geltungserhaltende Reduktion: Sie fällt ganz weg, auch wenn hier erst nach 4 Monaten geliefert wurde.", "Rechtsfolge § 306 I, II: Vertrag bleibt wirksam, es gilt der vereinbarte Preis von 15.700 €."], "o": [null, null, null, null, null, null]}, "W-7": {"k": "Nein; zwar nicht n", "w": ["Aushang am Ort des Vertragsschlusses kann genügen (§ 305 II Nr. 1 Alt. 2) → einbezogen.", "§ 309 Nr. 7: Absatz 2 betrifft nur Sachschäden und lässt die Haftung für grobes Verschulden bestehen → kein Verstoß.", "§ 307 I: Unangemessene Benachteiligung? Nach dem BGH ja: Wer eine Waschanlage betreibt, beherrscht die Gefahr; der Kunde kann sich nicht schützen. Gerade Schäden an Außenteilen sind das typische Risiko, für das der Kunde den Betreiber in Anspruch nehmen will.", "Folge: Absatz 2 ist unwirksam (§ 306 I); es gilt die gesetzliche Haftung."], "o": [null, null, null, null, null, null]}, "W-8": {"k": "Unwirksam, weil si", "w": ["Ingolf ist Unternehmer → § 310 I 1: §§ 308, 309 gelten nicht unmittelbar, § 307 aber schon.", "§ 305c I (überraschend)? Maßstab ist objektiv, nicht Ingolfs persönliche Überraschung; Vertragsstrafen sind in Werbeverträgen üblich.", "§ 307 I: Eine Strafe, die mehr als dreimal so hoch ist wie branchenüblich, benachteiligt unangemessen.", "Rechtsfolge: Klausel fällt ganz weg (§ 306 I, II) – keine Herabsetzung auf ein zulässiges Maß; § 343 hilft bei AGB nicht."], "o": [null, null, null, null, null, null]}, "fb-6-sm1": {"k": "Ja, weil die Bastl", "w": ["Verbrauchsgüterkauf (Händler – Studentin) → § 476 I: Vor Mitteilung eines Mangels darf nicht zum Nachteil des Verbrauchers von § 434 abgewichen werden.", "Ausnahme negative Beschaffenheitsvereinbarung (§ 476 I 2): Der Verbraucher muss vor Vertragsschluss eigens davon in Kenntnis gesetzt werden, und die Abweichung muss ausdrücklich und gesondert vereinbart werden.", "Eine Zeile auf Seite 3 der AGB, über die nicht gesprochen wurde, genügt nicht → „Bastlerfahrzeug“ gilt nicht.", "Ein Getriebeausfall nach zwei Wochen ist kein üblicher Verschleiß → Sachmangel. Vermutung des § 477 I hilft S beim Beweis."], "o": [null, null, null, null, null, null]}, "fb-6-sm2": {"k": "Nein, weil K S zue", "w": ["Lieferung eines anderen Modells = Falschlieferung (aliud). Sie steht einem Sachmangel gleich (§ 434 V) → Mängelrechte aus § 437.", "Vorrang der Nacherfüllung: Rücktritt (§ 323 I) und Schadensersatz statt der Leistung (§ 281 I) verlangen eine erfolglose Frist.", "Keine Entbehrlichkeit (§ 440, § 323 II): S hat nicht verweigert, die Nacherfüllung ist nicht fehlgeschlagen und nicht unzumutbar.", "K hat ohne Frist eingedeckt → weder Rückzahlung noch Mehrkosten."], "o": [null, null, null, null, null, null]}, "rh6-34": {"k": "Victoria erstattet", "w": ["Webshop, Verbraucherin – Unternehmerin → Fernabsatzvertrag → Widerrufsrecht (§§ 312c, 312g I).", "Rücktritt? Kein Rücktrittsgrund (kein Mangel, keine Frist). Die Erklärung „vom Kauf zurücktreten“ ist deshalb als Widerruf auszulegen (§ 133); ein Grund ist nicht nötig, das Wort „Widerruf“ auch nicht.", "Rechtsfolgen: Victoria erstattet Kaufpreis und Hinsendekosten (§ 357 I, II). Rücksendekosten trägt Karla, wenn sie darüber informiert wurde (§ 357 V).", "Wertersatz für den Wertverlust durch Tragen und Flecken: § 357a I – Umgang über die Prüfung hinaus, verschuldensunabhängig."], "o": [null, null, null, null, null, null]}, "rh6-35": {"k": "Karla kann den Ver", "w": ["Fernabsatzvertrag → Widerrufsrecht ohne Begründung (§ 355 I 4), unabhängig von Mängeln.", "Daneben Mängelrechte: Saum gelöst = Sachmangel → Nacherfüllung (§ 439). Die Ersatzlieferung umfasst aber nur dieselbe Sache mangelfrei – nicht eine andere Größe.", "Karlas Nachricht verlangt Nacherfüllung (bzw. Umtausch), keinen Rücktritt. Minderung setzt eine erfolglose Frist voraus.", "Richtig ist deshalb nur: Sie kann ohne Begründung widerrufen."], "o": [null, null, null, null, null, null]}, "rh6-36": {"k": "V hätte K ermöglic", "w": ["Einbeziehung gegenüber Verbrauchern (§ 305 II): ausdrücklicher Hinweis bei Vertragsschluss (Nr. 1) + Möglichkeit zumutbarer Kenntnisnahme (Nr. 2) + Einverständnis.", "Hinweis: im Angebot erfolgt. Einverständnis: konkludent durch Bestellung „zu den genannten Bedingungen“.", "Kenntnisnahme: Auslegen im Stuttgarter Geschäft ist für einen Münchner Kunden nicht zumutbar → V hätte sie z. B. zusenden müssen."], "o": [null, null, null, null, null, null]}, "rh6-37": {"k": "Der Hinweis in der", "w": ["Der Hinweis ist für viele Verträge vorformuliert und wird gestellt → AGB (§ 305 I), auch digital.", "K ist Unternehmer → § 305 II, III gelten nicht (§ 310 I 1). Nötig ist aber eine Einbeziehungsvereinbarung bei Vertragsschluss – der gut lesbare Hinweis über dem Bestell-Button genügt; K bestellt trotzdem.", "Inhalt: Gegenüber Unternehmern nur § 307. Ein Ausschluss für leicht fahrlässige Sachschäden ist dort nicht von vornherein unwirksam."], "o": [null, null, null, null, null, null]}, "rh6-38": {"k": "Fehlt eine ordnung", "w": ["Widerrufsrecht nur bei Fernabsatz- und Außergeschäftsraumverträgen (§ 312g I) – nicht im Laden.", "Frist: 14 Tage (§ 355 II 1), Beginn grundsätzlich mit Vertragsschluss, beim Warenkauf mit Erhalt (§ 356 II). Kein Grund nötig (§ 355 I 4).", "Ohne ordnungsgemäße Belehrung beginnt die Frist nicht (§ 356 III 1); das Recht erlischt aber spätestens 12 Monate und 14 Tage nach Erhalt (§ 356 III 2).", "§ 193 verschiebt nur das Fristende, nicht den Beginn."], "o": [null, null, null, null, null, null]}, "rh6-39": {"k": "Die Widerrufsfrist", "w": ["Fernabsatzvertrag, Modeschmuck ist keine Ausnahme nach § 312g II → Widerrufsrecht, 14 Tage (§ 355 II 1).", "Beginn: Erhalt der Ware (§ 356 II Nr. 1 a) am Sa 7.5. Ereignisfrist → der Tag zählt nicht mit (§ 187 I) → Fristbeginn So 8.5.", "Ende nach 14 Tagen: Sa 21.5. (§ 188 I). Fällt das Ende auf einen Samstag, verschiebt § 193 auf Mo 23.5.", "Auspacken durch die Tochter ist unerheblich."], "o": [null, null, null, null, null, null]}, "rh6-44": {"k": "Nein, weil ein Aus", "w": ["Einbezogen sind die AGB: deutlich sichtbar, von K zur Kenntnis genommen (§ 305 II).", "Inhaltskontrolle § 309 Nr. 7 a: Ausschluss oder Begrenzung der Haftung für fahrlässig verursachte Schäden an Leben, Körper, Gesundheit ist in AGB unwirksam.", "Folge: Klausel fällt weg (§ 306 I, II); U haftet wie im Ausgangsfall."], "o": [null, null, null, null, null, null]}, "h13": {"k": "Der Widerruf ist r", "w": ["Fernabsatzvertrag, keine Widerrufsbelehrung → Frist beginnt nicht (§ 356 III 1). Erlöschen erst nach 12 Monaten und 14 Tagen (§ 356 III 2) → Widerruf am 20.7. rechtzeitig.", "Wertersatz für Nutzung über die Prüfung hinaus (§ 357a I) setzt u. a. voraus, dass ordnungsgemäß über das Widerrufsrecht belehrt wurde (§ 357a I Nr. 2) → entfällt.", "Rücksendekosten trägt der Verbraucher nur, wenn er darüber informiert wurde (§ 357 V) → Händler trägt die 89 €.", "Rad & Co muss die einbehaltenen 500 € erstatten."], "o": [null, null, null, null, null, null]}, "h14": {"k": "Es gelten 3 Jahre,", "w": ["Zwei Unternehmer; AGB durch deutlichen Hinweis im Angebot einbezogen.", "Der Vertriebsleiter mit Abschlussvollmacht sagt mündlich drei Jahre zu → Individualabrede.", "§ 305b: Individuelle Vertragsabreden haben Vorrang vor AGB – auch vor einer formularmäßigen Schriftformklausel.", "Es gelten drei Jahre; auf die Inhaltskontrolle der 6-Monats-Klausel kommt es nicht an."], "o": [null, null, null, null, null, null]}, "L2-8": {"k": "Nein: Der Vertrag ", "w": ["Vertrag kam am Telefon zustande, ohne Hinweis auf AGB.", "§ 305 II: Der Hinweis muss bei Vertragsschluss erfolgen. Ein Aushang genügt nur, wenn ein ausdrücklicher Hinweis unverhältnismäßig schwierig ist – am Telefon war er leicht möglich, und G sah den Aushang erst nach Vertragsschluss.", "Meldeschein und Rechnung kommen nach Vertragsschluss → zu spät.", "Es gilt das Gesetz: Gastwirtshaftung (§ 701) und Haftung für den Mitarbeiter (§§ 280 I, 241 II, 278)."], "o": [null, null, null, null, null, null]}, "L2-9": {"k": "Die Klausel ist un", "w": ["Einbeziehung: deutlicher Hinweis, AGB lagen vor → einbezogen.", "§ 309 Nr. 7 a: Für Körperschäden ist in AGB schon der Ausschluss der Haftung für einfache Fahrlässigkeit unwirksam. Die Klausel lässt nur Vorsatz übrig → unwirksam.", "Keine geltungserhaltende Reduktion; es gilt die gesetzliche Haftung (§ 306 II).", "Anspruch aus §§ 280 I, 241 II (unterlassene Wartung): Behandlungskosten und Schmerzensgeld (§ 253 II)."], "o": [null, null, null, null, null, null]}, "fb-8-agb1": {"k": "Nein. Die AGB wurd", "w": ["Einbeziehung (§ 305 II): Hinweis muss bei Vertragsschluss erfolgen. Auftrag wurde mündlich am Tresen ohne Hinweis erteilt.", "AGB auf der Rechnung bei Abholung kommen nach Vertragsschluss; Schweigen und Zahlen ist kein Einverständnis.", "Ohne Einbeziehung kommt es auf die Inhaltskontrolle nicht an.", "W haftet für den Mechaniker aus §§ 280 I, 241 II, 278 (bzw. Mängelrecht § 634) auf 800 €."], "o": [null, null, null, null, null, null]}, "fb-8-agb2": {"k": "Nein; die Abo-Klau", "w": ["Einbeziehung per Häkchen grundsätzlich wirksam.", "§ 305c I: Überraschende Klauseln werden trotzdem nicht Vertragsbestandteil. Ein 24-monatiges Kapsel-Abo, versteckt unter „Sonstiges“ beim Kauf einer 49-€-Maschine, ist objektiv ungewöhnlich – damit muss niemand rechnen.", "Rechtsfolge § 306 I: Der Maschinenkauf bleibt wirksam; nur die Abo-Klausel fällt weg. § 139 wird verdrängt."], "o": [null, null, null, null, null, null]}, "fb-8-agb3": {"k": "Nein, die Klausel ", "w": ["Die Klausel schließt „Schäden aller Art“ aus, also auch Körperschäden und grobe Fahrlässigkeit.", "§ 309 Nr. 7 a (Körper) und Nr. 7 b (grobe Fahrlässigkeit) → unwirksam.", "Kein „Rest“: Eine geltungserhaltende Reduktion auf den zulässigen Teil (Sachschäden bei leichter Fahrlässigkeit) gibt es nicht. Die Klausel fällt ganz weg (§ 306 II).", "F haftet für Behandlungskosten und Smartwatch."], "o": [null, null, null, null, null, null]}, "a6-14": {"k": "Nein, weil der Hin", "w": ["Zwei GmbHs → § 305 II gilt nicht (§ 310 I 1). Trotzdem müssen AGB bei Vertragsschluss – auch stillschweigend – vereinbart werden.", "Der Vertrag stand mit der mündlichen Einigung. Die AGB wurden erst danach überreicht.", "Ein nachträglicher Hinweis ändert den geschlossenen Vertrag nicht; ein kaufmännisches Bestätigungsschreiben liegt nicht vor → nicht einbezogen."], "o": [null, null, null, null, null, null]}, "a6-15": {"k": "Die Frist läuft er", "w": ["Fernabsatz, ordnungsgemäße Belehrung → 14 Tage ab Erhalt der Ware (§§ 355 II 1, 356 II Nr. 1 a).", "Erhalt Di 21.5.; der Ereignistag zählt nicht (§ 187 I) → Beginn Mi 22.5.", "Ende nach 14 Tagen am Di 4.6., 24 Uhr (§ 188 I). Widerruf am 3.6. ist rechtzeitig."], "o": [null, null, null, null, null, null]}, "a6-26": {"k": "Wenn er nicht ordn", "w": ["Bei ordnungsgemäßer Belehrung: 14 Tage ab Erhalt (14.12.) → Beginn 15.12. (§ 187 I), Ende 28.12. Am 30.12. wäre es zu spät.", "Mangel, späteres Auspacken oder eine Bestätigungsmail verschieben die Frist nicht.", "Nur ohne ordnungsgemäße Belehrung beginnt die Frist nicht (§ 356 III 1) → Widerruf am 30.12. möglich."], "o": [null, null, null, null, null, null]}, "a6-36": {"k": "Nein. Die AGB ist ", "w": ["Vorformuliert für viele Verträge → AGB (§ 305 I); es genügt die Absicht mehrfacher Verwendung, auch beim ersten Kunden.", "§ 309 Nr. 7 a: Für Körperschäden ist auch der Ausschluss der Haftung für leichte Fahrlässigkeit unwirksam.", "Klausel fällt weg; F haftet aus §§ 280 I, 241 II einschließlich Schmerzensgeld (§ 253 II)."], "o": [null, null, "§ 309 Nr. 7 a verbietet in AGB gerade den Ausschluss für leicht fahrlässige Körperverletzungen. Eine Platzwunde ist ein Körperschaden.", null, null, null]}, "a6-51": {"k": "Ein vollumfänglich", "w": ["Händler an Verbraucher → Verbrauchsgüterkauf. § 476 I: Mängelrechte können vor Mitteilung des Mangels nicht zum Nachteil des Verbrauchers ausgeschlossen werden – auch nicht gegen Preisnachlass.", "Negative Beschaffenheitsvereinbarung nur mit eigens erteiltem Hinweis und gesonderter Vereinbarung (§ 476 I 2).", "Ein vollständiger Ausschluss in AGB verstößt zudem gegen § 309 Nr. 7 (Körper, grobe Fahrlässigkeit).", "Verjährung bei gebrauchten Sachen: Verkürzung höchstens auf 1 Jahr (§ 476 II)."], "o": ["Beim Verbrauchsgüterkauf kann der Händler seine Haftung für Mängel vor deren Mitteilung nicht ausschließen (§ 476 I).", null, "Wer ohne Kenntnis Angaben „ins Blaue hinein“ macht und dabei Sicherheit vorspiegelt, handelt bedingt vorsätzlich – das ist Arglist.", null, null, null]}, "a6-60": {"k": "Fehlt eine ordnung", "w": ["Widerrufsrecht nur bei Fernabsatz- und Außergeschäftsraumverträgen (§ 312g I).", "Frist 14 Tage; beim Warenkauf ab Erhalt (§ 356 II). Ohne ordnungsgemäße Belehrung beginnt sie nicht (§ 356 III 1).", "Erklärung formfrei, aber eindeutig; keine Begründung (§ 355 I). Der Unternehmer erstattet auch die Hinsendekosten (§ 357 II)."], "o": [null, null, null, "§ 193 verschiebt nur das Ende einer Frist, die auf einen Sonntag, Feiertag oder Samstag fällt. Für den Beginn gilt das nicht.", null, null]}, "L2-10": {"k": "Ja: Die Frist lief", "w": ["Fernabsatz, ordnungsgemäße Belehrung → 14 Tage ab Erhalt der Ware (§§ 355 II, 356 II Nr. 1 a), nicht ab Bestellung.", "Erhalt Mo 3.3.; der Ereignistag zählt nicht (§ 187 I) → Beginn 4.3., Ende Mo 17.3., 24 Uhr (§ 188 I).", "Zur Fristwahrung genügt die rechtzeitige Absendung (§ 355 I 5). Dass die Mail nach Geschäftsschluss zugeht, ist unerheblich → rechtzeitig."], "o": [null, null, null, null, null, null]}, "L2-11": {"k": "Kommentarloses Zur", "w": ["Der Widerruf ist formfrei, verlangt aber eine Erklärung, aus der der Entschluss zum Widerruf eindeutig hervorgeht (§ 355 I 2, 3).", "Kommentarloses Zurückschicken genügt seit 2014 nicht mehr – es könnte auch ein Umtausch oder eine Reklamation gemeint sein.", "Die E-Mail nach über drei Wochen ist eindeutig, aber verspätet: Die 14-Tage-Frist (Erhalt + 14) ist abgelaufen."], "o": [null, null, null, null, null, null]}, "L2-12": {"k": "Nein, für nach Kun", "w": ["Grundsätzlich Widerrufsrecht im Fernabsatz (§ 312g I).", "Ausnahme § 312g II Nr. 1: Waren, die nach Kundenspezifikation angefertigt werden oder eindeutig auf persönliche Bedürfnisse zugeschnitten sind.", "Der Anzug wurde nach Vs individuellen Körpermaßen geschneidert → ein anderer Kunde passt kaum hinein → kein Widerrufsrecht. Auf Wertersatz kommt es nicht an."], "o": [null, null, null, null, null, null]}, "PK-10": {"k": "Die Klausel ist un", "w": ["Online-Kauf einer neuen Sache durch einen Verbraucher → Verbrauchsgüterkauf.", "Gesetzliche Verjährung 2 Jahre (§ 438 I Nr. 3). § 476 II: Vor Mitteilung des Mangels ist eine Verkürzung bei neuen Sachen unter 2 Jahre unzulässig; nur bei gebrauchten Sachen bis auf 1 Jahr, und dann nur mit Hinweis und gesonderter Vereinbarung.", "Die 6-Monats-Klausel ist unwirksam; es gelten 2 Jahre (§ 306 II). Nach 10 Monaten bestehen die Mängelrechte."], "o": [null, null, null, null, null, null]}, "PK-11": {"k": "Die mündliche Zusa", "w": ["Mündliche feste Zusage „bis spätestens 1. Juni“ = Individualabrede.", "§ 305b: Individuelle Vertragsabreden haben Vorrang vor AGB.", "Das gilt auch gegenüber einer AGB-Schriftformklausel – sonst könnte sich der Verwender durch AGB von seinen eigenen Zusagen lösen.", "M muss bis 1. Juni liefern."], "o": [null, null, null, null, null, null]}, "fb-7-vgk1": {"k": "Nein. Die Verkürzu", "w": ["Gebrauchtwagen, Händler an Verbraucher → Verbrauchsgüterkauf; gesetzlich 2 Jahre (§ 438 I Nr. 3).", "Verkürzung bei gebrauchten Sachen auf 1 Jahr ist möglich, aber nur, wenn der Verbraucher vor Vertragsschluss eigens darauf hingewiesen und die Verkürzung ausdrücklich und gesondert vereinbart wurde (§ 476 II).", "Bloß in den AGB unterschrieben, nicht besprochen → unwirksam → 2 Jahre. Nach 18 Monaten nicht verjährt; K muss den Mangel aber selbst beweisen (Vermutung des § 477 I nur 1 Jahr)."], "o": [null, null, null, null, null, null]}, "P2-frist-0": {"k": "Bis Montag, 23. 3.", "w": ["14 Tage ab Erhalt der Ware (§ 356 II Nr. 1 a), nicht ab Bestellung.", "Erhalt Sa 7.3.; Ereignistag zählt nicht (§ 187 I) → Beginn So 8.3.", "Ende nach 14 Tagen: Sa 21.3. (§ 188 I). Fällt das Ende auf einen Samstag, verschiebt § 193 es auf Mo 23.3."], "o": [null, null, null, null, null, null]}, "P2-frist-1": {"k": "Der Widerruf ist r", "w": ["Der Widerruf ist eine empfangsbedürftige Erklärung und wird mit Zugang wirksam.", "Für die Fristwahrung genügt aber die rechtzeitige Absendung (§ 355 I 5) → Einwurf am Dienstagabend reicht.", "Form und Begründung sind nicht nötig; die Rücksendung der Ware ist Folge, nicht Voraussetzung."], "o": [null, null, null, null, null, null]}, "P2-frist-2": {"k": "Rechtzeitig; ohne ", "w": ["Fernabsatz ohne Belehrung → die 14-Tage-Frist beginnt nicht (§ 356 III 1).", "Das Widerrufsrecht erlischt aber spätestens 12 Monate und 14 Tage nach Erhalt der Ware (§ 356 III 2) → hier Ende Januar 2026.", "Der Widerruf am 20.12.2025 ist rechtzeitig. Die Nutzung schließt ihn nicht aus."], "o": [null, null, null, null, null, null]}, "P2-frist-3": {"k": "Kein Widerrufsrech", "w": ["Fernabsatz → grundsätzlich Widerrufsrecht.", "Ausnahme § 312g II Nr. 1: nach Kundenspezifikation angefertigte Waren. Eigene Maße, Stoff und Knöpfe → eindeutig auf K zugeschnitten.", "Kein Widerrufsrecht; ob der Anzug gefällt oder getragen wurde, ist gleichgültig."], "o": [null, null, null, null, "Auch Werklieferungsverträge (§ 650) können widerrufen werden. Der Ausschluss folgt allein aus der Anfertigung nach Kundenwunsch.", null]}, "P2-frist-4": {"k": "Der Widerruf ist m", "w": ["Ausnahme § 312g II Nr. 3: versiegelte Waren, die aus Gesundheits- oder Hygienegründen nicht zur Rückgabe geeignet sind, wenn die Versiegelung entfernt wurde.", "EuGH (Slewo, 2019): Eine Matratze kann – wie Kleidung – gereinigt und wieder verkauft werden. Sie fällt nicht unter die Ausnahme.", "V kann widerrufen; für die Nutzung über die Prüfung hinaus kommt allenfalls Wertersatz in Betracht (§ 357a I)."], "o": [null, null, null, null, null, "§ 312g II Nr. 3 gilt für alle versiegelten Waren, die aus Hygienegründen nicht zurückgegeben werden können, z. B. Zahnbürsten oder Kosmetik – nicht nur für Lebensmittel."]}, "P2-frist-5": {"k": "Kein Anspruch: Im ", "w": ["Gesetzliches Widerrufsrecht nur im Fernabsatz oder außerhalb von Geschäftsräumen (§ 312g I) – nicht beim Kauf im Laden.", "Rücktritt braucht einen Mangel; Nichtgefallen ist keiner. Ein Irrtum über den eigenen Geschmack ist ein unbeachtlicher Motivirrtum.", "Ohne freiwillige Rücknahme (Kulanz) oder vertragliches Rückgaberecht hat K keinen Anspruch."], "o": [null, null, null, null, null, null]}, "P2-frist-6": {"k": "Wirksam; V schulde", "w": ["Wirksamer Widerruf im Fernabsatz; Nutzung schließt ihn nicht aus.", "Wertersatz (§ 357a I): für Wertverlust durch einen Umgang, der zur Prüfung von Beschaffenheit, Eigenschaften und Funktionsweise nicht notwendig war – und nur bei ordnungsgemäßer Belehrung (Nr. 2).", "Zehn Tage tägliche Nutzung ohne Entkalken geht über die Prüfung hinaus → Ersatz des Wertverlusts, nicht des Kaufpreises; verschuldensunabhängig."], "o": [null, null, null, null, null, null]}, "P2-frist-7": {"k": "Der Widerruf ist w", "w": ["Widerruf = Erklärung gegenüber dem Unternehmer, aus der der Entschluss eindeutig hervorgeht (§ 355 I 2, 3).", "Keine Form (auch telefonisch), keine Begründung (§ 355 I 4), kein Musterformular nötig.", "Wirksam mit Zugang. K trägt nur das Beweisrisiko, dass er rechtzeitig widerrufen hat."], "o": [null, null, null, null, null, null]}, "P2-frist-8": {"k": "H darf die Rückzah", "w": ["Nach Widerruf muss H binnen 14 Tagen erstatten (§ 357 I), einschließlich der Standard-Hinsendekosten, mit demselben Zahlungsmittel (§ 357 III).", "Beim Warenkauf darf H die Rückzahlung aber verweigern, bis er die Ware zurückerhalten oder V den Nachweis der Absendung erbracht hat (§ 357 IV) – außer, er hat angeboten, die Ware abzuholen.", "H hat nicht angeboten abzuholen → Zurückbehaltungsrecht."], "o": [null, null, null, null, null, null]}, "P2-frist-9": {"k": "Nein, weil es eine", "w": ["Online-Ticketkauf ist zwar Fernabsatz.", "§ 312g II Nr. 9: kein Widerrufsrecht bei Verträgen über Freizeitbetätigungen, wenn der Vertrag einen spezifischen Termin vorsieht.", "Das Konzert hat einen festen Termin → kein Widerruf; Abstand zum Termin und Preis spielen keine Rolle."], "o": [null, null, null, null, null, null]}, "rh6-8": {"k": "Nein, weil der For", "w": ["Schenkungsversprechen bedarf notarieller Beurkundung (§ 518 I) – fehlte.", "Heilung (§ 518 II): Mit Bewirken der Leistung, hier Übergabe der 500 €, wird der Formmangel geheilt → wirksamer Rechtsgrund.", "Rückforderung nur bei Widerruf wegen groben Undanks (§ 530): verlangt eine schwere Verfehlung gegenüber der Schenkerin. Den Freund einzuladen ist keine."], "o": [null, null, null, null, null, null]}, "fb-3-erl2": {"k": "Der Vertrag besteh", "w": ["Fitnessvertrag = Dauerschuldverhältnis → statt Rücktritt nur Kündigung, aus wichtigem Grund nach § 314.", "Wichtiger Grund: Fortsetzung unzumutbar, Grund nicht in der eigenen Risikosphäre. Ein Umzug liegt nach dem BGH (XII ZR 62/15) in der Sphäre der Kundin → kein wichtiger Grund.", "Eine Laufzeit von 24 Monaten ist zulässig (§ 309 Nr. 9 a). Selbst eine wirksame Kündigung wirkte nur für die Zukunft – bereits gezahlte Beiträge gibt es nie zurück."], "o": [null, null, null, null, null, null]}, "fb-9-abtr": {"k": "Die Abtretung ist ", "w": ["Grundsatz § 399: Ein vereinbartes Abtretungsverbot macht die Abtretung unwirksam.", "Ausnahme § 354a I 1 HGB: Ist das Geschäft für beide ein Handelsgeschäft (GmbH, AG), ist die Abtretung einer Geldforderung trotzdem wirksam → F ist Gläubigerin.", "§ 354a I 2 HGB: Der Schuldner A darf aber weiterhin mit befreiender Wirkung an den bisherigen Gläubiger M leisten → A ist frei. F muss sich an M halten."], "o": [null, null, null, null, null, null]}, "fb-8-wr1": {"k": "Ja; das Fristende ", "w": ["14 Tage ab Erhalt (Sa 4.7.); Ereignistag zählt nicht (§ 187 I) → Beginn So 5.7.", "Rechnerisches Ende: Sa 18.7. (§ 188 I). § 193 gilt auch für die Widerrufsfrist: Fällt das Ende auf einen Samstag, endet sie am nächsten Werktag, Mo 20.7.", "Die E-Mail am 20.7. ist rechtzeitig (Absendung genügt, § 355 I 5)."], "o": [null, null, null, null, null, null]}, "fb-8-wr2": {"k": "1, 3 und 5", "w": ["Keine Belehrung → Frist beginnt nicht (§ 356 III 1). Erlöschen erst 12 Monate und 14 Tage nach Erhalt (§ 356 III 2) → Widerruf im November 2026 rechtzeitig (Aussage 1); unbegrenzt ist das Recht aber nicht (Aussage 2 falsch).", "Folge: U muss die 400 € erstatten (§ 357 I, Aussage 3).", "Wertersatz für Nutzung setzt ordnungsgemäße Belehrung voraus (§ 357a I Nr. 2) → entfällt (Aussage 5; Aussage 4 falsch).", "Richtig: 1, 3 und 5."], "o": [null, null, null, null, null, null]}, "fb-8-wr3": {"k": "Nein. Bei personal", "w": ["Fernabsatz → grundsätzlich Widerrufsrecht (§ 312g I).", "Ausnahme § 312g II Nr. 1: Waren, die eindeutig auf die persönlichen Bedürfnisse zugeschnitten sind. Ein Hoodie mit Name und Lieblingszahl ist personalisiert und schwer weiterzuverkaufen.", "Kein Widerrufsrecht. Nichtgefallen der Farbe ist auch kein Mangel."], "o": [null, null, null, null, null, null]}, "fb-2-vs2": {"k": "R muss weder zahle", "w": ["Unbestellte Lieferung eines Unternehmers an eine Verbraucherin → § 241a I.", "Kein Vertrag: Schweigen ist keine Annahme; die einseitige Fristsetzung ändert daran nichts.", "§ 241a I schließt alle Ansprüche aus – Zahlung, Rücksendung, Herausgabe (§ 985) und Nutzungsersatz. R muss nichts tun."], "o": [null, null, null, null, null, null]}, "fb-2-we1": {"k": "G ist gebunden, ka", "w": ["Äußerer Tatbestand: Handheben gilt laut Aushang als Gebot (§ 156: Zuschlag = Annahme).", "Innerer Tatbestand: Handlungswille ja, Erklärungsbewusstsein nein. Nach dem BGH trotzdem Willenserklärung, wenn G bei verkehrsüblicher Sorgfalt hätte erkennen können, dass sein Winken als Gebot verstanden wird.", "G kann analog § 119 I anfechten – unverzüglich (§ 121) – und schuldet dann den Vertrauensschaden (§ 122), nicht den Kaufpreis."], "o": [null, null, null, null, null, null]}, "fb-2-wh1": {"k": "A muss weder übere", "w": ["A erklärt laut lachend am Stammtisch und erwartet, dass B den Scherz erkennt → Scherzerklärung (§ 118) → nichtig. Kein geheimer Vorbehalt (§ 116) und kein Scheingeschäft (§ 117), weil B nicht eingeweiht ist.", "Vertrauensschaden nach § 122 I grundsätzlich auch bei § 118.", "Ausschluss § 122 II: Kein Ersatz, wenn der Geschädigte die Nichtigkeit kannte oder kennen musste. Ein Porsche für 1 € unter Gelächter – das musste B erkennen → keine 1.500 €."], "o": [null, null, null, null, null, null]}, "rh6-10": {"k": "M hat gegenüber G ", "w": ["Anfechtung? M wusste, was sie kaufte und zu welchem Preis. Sie irrte nur über Maiks Interesse → Motivirrtum, unbeachtlich.", "Rücktritt? Setzt einen Mangel voraus – die Figuren sind mangelfrei. § 313 scheidet aus: Das Verwendungsrisiko trägt der Käufer.", "Widerruf? Nur bei Fernabsatz oder außerhalb von Geschäftsräumen – nicht im Einkaufszentrum.", "Ein gesetzliches Umtauschrecht gibt es nicht → nur Kulanz."], "o": [null, null, null, null, null, null]}, "rh6-11": {"k": "Die Schadensersatz", "w": ["§ 122 I: Wer nach §§ 118, 119, 120 nichtig ist bzw. anficht, ersetzt den Vertrauensschaden – verschuldensunabhängig (Veranlassungsprinzip), begrenzt durch das Erfüllungsinteresse.", "Bei Anfechtung wegen Täuschung oder Drohung (§ 123) gibt es keinen § 122.", "§ 119 II erfasst Eigenschaften der Person oder Sache. Die Anfechtungserklärung ist empfangsbedürftig (§ 143 I). Frist bei Irrtum: unverzüglich (§ 121)."], "o": [null, null, null, null, null, null]}, "fb-7-aus": {"k": "V haftet für den Ö", "w": ["Unter Privatleuten ist ein Gewährleistungsausschluss grundsätzlich wirksam.", "Rost: K hat ihn bei der Besichtigung gesehen → Kenntnis bei Vertragsschluss → keine Mängelrechte (§ 442 I 1), unabhängig vom Ausschluss.", "Ölverlust: V kannte ihn und schwieg trotz Aufklärungspflicht → Arglist → auf den Ausschluss kann er sich nicht berufen (§ 444). K hat Mängelrechte, ohne anfechten zu müssen."], "o": [null, null, null, null, null, null]}, "h7": {"k": "Nein, ein Kalkulat", "w": ["Erklärungsirrtum (§ 119 I Alt. 2)? Nein – U wollte genau „46.800 €“ schreiben.", "Inhaltsirrtum (§ 119 I Alt. 1)? Nein – U wusste, was „46.800 €“ bedeutet. Er irrte bei der Berechnung, also im Vorfeld der Erklärung.", "Kalkulationsirrtum = Motivirrtum, auch wenn die Positionen offengelegt sind (BGH). Ausnahme allenfalls über § 242, wenn K den Fehler erkannt und den Vertrag treuwidrig durchgesetzt hätte – K prüfte nicht nach.", "Ergebnis: keine Anfechtung; es bleibt bei 46.800 €."], "o": [null, null, null, null, null, null]}, "h8": {"k": "Vincent kann binne", "w": ["Hahn behauptet wider besseres Wissen Unfallfreiheit → arglistige Täuschung → Anfechtung nach § 123 I. Frist: 1 Jahr ab Entdeckung (§ 124 I, II) → im Februar gewahrt.", "Daneben Mängelrechte: Unfallschaden = Sachmangel. Bei Arglist ist Nacherfüllung unzumutbar → Rücktritt ohne Frist (§§ 440, 323 II Nr. 3).", "„Gekauft wie besichtigt“ hilft nicht: Bei Arglist kein Ausschluss (§ 444); auch § 442 I 2 greift bei Arglist nicht.", "§ 123 wird – anders als § 119 II – nicht durch das Kaufrecht verdrängt."], "o": [null, null, null, null, null, null]}, "L2-4": {"k": "H hat wegen Erklär", "w": ["Vertragsschluss: Ks Bestellung = Angebot, die automatische Bestätigung „Kaufvertrag ist geschlossen“ = Annahme der H (automatisiert erstellt, aber ihr zurechenbar).", "Der Tippfehler bei der Eingabe setzt sich in der Annahme fort → Erklärungsirrtum (§ 119 I Alt. 2; BGH). Verschulden schadet nicht.", "Anfechtung am nächsten Morgen, 20 Minuten nach Entdeckung → unverzüglich (§ 121). Vertrag nichtig (§ 142 I).", "K bekommt den Vertrauensschaden (§ 122): das nicht stornierbare Schloss, 39 € – nicht den Preisvorteil."], "o": [null, null, null, null, null, null]}, "L2-5": {"k": "Nein: Es liegt ein", "w": ["§ 119 II? Ertragsaussichten und Kursentwicklung sind keine verkehrswesentlichen Eigenschaften der Aktie, sondern Erwartungen → Motivirrtum.", "§ 119 I? K wollte genau diese Aktien zu diesem Preis → kein Inhalts- oder Erklärungsirrtum.", "§ 123? Getäuscht hat – wenn überhaupt – ein Dritter (Forum). Dann nur Anfechtung, wenn der Verkäufer die Täuschung kannte oder kennen musste (§ 123 II 1) → nein.", "Ohne Anfechtungsgrund hilft auch eine unverzügliche Erklärung nicht. § 313 scheidet aus: Kursrisiko trägt der Käufer."], "o": [null, null, null, null, null, null]}, "L2-6": {"k": "K kann wegen Täusc", "w": ["V lügt auf direkte Frage → arglistige Täuschung (§ 123 I).", "Frist: 1 Jahr ab Entdeckung (§ 124 I, II) → nach 10 Monaten, sofort nach Kenntnis → gewahrt. § 121 gilt nur bei Irrtum.", "Der Gewährleistungsausschluss erfasst die Anfechtung nicht; bei Arglist wirkt er nicht einmal für die Mängelrechte (§ 444).", "§ 122 gilt bei § 123 nicht → K schuldet V nichts. Rückabwicklung nach § 812."], "o": [null, null, null, null, null, null]}, "L2-7": {"k": "Die Anfechtung ist", "w": ["Vereinbart war echtes Rindsleder, geliefert Kunstleder → Abweichung von der vereinbarten Beschaffenheit → Sachmangel (§ 434 II 1 Nr. 1).", "Ks Irrtum betrifft genau diese Beschaffenheit. Nach Gefahrübergang verdrängen die Mängelrechte die Anfechtung nach § 119 II – sonst würde das Recht des Verkäufers zur zweiten Andienung umgangen.", "K muss deshalb zuerst Nacherfüllung zulassen (§§ 437 Nr. 1, 439). Rücktritt erst nach erfolgloser Frist."], "o": [null, null, "Kunstleder statt Rindsleder ist eine Abweichung von der vereinbarten Beschaffenheit (§ 434 II). Auch hier gilt der Vorrang der Nacherfüllung; sofort zurücktreten kann K nicht.", null, null, null]}, "a6-0": {"k": "Sind Verpflichtung", "w": ["Anfechtung wirkt zurück: Das angefochtene Geschäft ist von Anfang an nichtig (§ 142 I).", "Abstraktionsprinzip: Grundsätzlich wird nur der Kaufvertrag angefochten; die Übereignung bleibt wirksam → K bleibt Eigentümer, V hat nur § 812.", "Fehleridentität (z. B. arglistige Täuschung): Auch die Übereignung kann angefochten werden → dann ist V Eigentümer geblieben und hat § 985 und § 812."], "o": [null, "Ist auch die Übereignung nichtig, hat das Eigentum nie gewechselt. Dann ist V Eigentümer geblieben, nicht K.", null, null, null, null]}, "a6-7": {"k": "Für die Anpassung ", "w": ["Störung der Geschäftsgrundlage (§ 313 I): Umstände, die zur Grundlage des Vertrags geworden sind, ändern sich nach Vertragsschluss schwerwiegend.", "Geprüft wird also: Wie war es bei Vertragsschluss, wie ist es jetzt – und ist das Festhalten unter Abwägung beider Seiten unzumutbar?", "G hat seine Einkünfte nicht offengelegt → sie sind nicht Geschäftsgrundlage geworden. Folge von § 313 wäre ohnehin ein Anspruch auf Anpassung, keine einseitige Kürzung."], "o": [null, null, null, null, null, null]}, "W-15": {"k": "Nein, die „Widerru", "w": ["Richard sagt „Powerbank“, meint aber Hantelbank. Objektiv (Empfängerhorizont) ist ein Ladegerät bestellt → Vertrag über die Powerbank.", "Er wusste, was er sagte, irrte aber über die Bedeutung des Wortes → Inhaltsirrtum (§ 119 I Alt. 1).", "Ein Widerrufsrecht hilft nicht weiter, sein „Widerruf“ ist aber als Anfechtung auszulegen (§ 133) → Vertrag nichtig (§ 142 I); keine Zahlung. Das Kaufhaus kann den Vertrauensschaden verlangen (§ 122)."], "o": [null, "Falsa demonstratio verlangt, dass beide dasselbe meinen. Die Mitarbeiterin verstand ein Ladegerät, Richard meinte eine Hantelbank.", null, null, null, null]}, "a6-17": {"k": "K hat keinen Anspr", "w": ["Ks Bestellung zu 1.200 € ist das Angebot. Vs Bestätigung zu 1.000 € ändert den Preis → Ablehnung und neues Angebot (§ 150 II). K nimmt mit „Einverstanden“ an → Vertrag zu 1.000 €.", "V hat sich vertippt → Erklärungsirrtum (§ 119 I Alt. 2).", "„Widerrufe“ ist als Anfechtung auszulegen (§ 133), sofort erklärt → unverzüglich (§ 121) → Vertrag nichtig. K hat keinen Lieferanspruch; er bekommt allenfalls Vertrauensschaden."], "o": [null, null, null, null, null, null]}, "a6-25": {"k": "Er zahlt den Preis", "w": ["Michaels Bestellung = Angebot zu den genannten Preisen; „Gut, wir liefern wie bestellt“ = Annahme → Vertrag ohne Rabatt.", "Ein geschlossener Vertrag kann nicht einseitig geändert werden; § 150 II betrifft nur die Annahme.", "Die Erwartung eines Rabatts ist ein Motivirrtum; ein kaufmännisches Bestätigungsschreiben gibt nur Verhandeltes wieder."], "o": [null, "Über den Preis gab es eine Einigung: Michael bestellte zu den Preisen aus dem Angebot, GreenHarvest nahm an. Der Rabatt kam erst danach auf.", null, null, null, null]}, "a6-33": {"k": "… nur 2.000 € verl", "w": ["Nach wirksamer Irrtumsanfechtung schuldet der Anfechtende den Vertrauensschaden (§ 122 I), ohne Verschulden.", "Vertrauensschaden: V hat im Vertrauen auf den Vertrag das Angebot des B abgelehnt → entgangener Gewinn 6.000 € − 3.000 € = 3.000 €.", "Obergrenze: das Erfüllungsinteresse – was V bei Erfüllung des Vertrags mit K gehabt hätte: 5.000 € − 3.000 € = 2.000 €.", "Ergebnis: 2.000 €."], "o": [null, null, null, null, null, null]}, "a6-40": {"k": "… wirksam, weil di", "w": ["V versichert wider besseres Wissen Unfallfreiheit → arglistige Täuschung (§ 123 I).", "Frist: 1 Jahr, beginnend mit Entdeckung der Täuschung (§ 124 I, II) – hier 2.2.2022. Anfechtung am 3.8.2022 → gewahrt.", "§ 121 (unverzüglich) gilt nur für §§ 119, 120. § 122 gilt bei § 123 nicht."], "o": [null, null, null, null, null, null]}, "a6-47": {"k": "V kann Schadensers", "w": ["Mietvertrag: Der Mieter darf die Sache nur vertragsgemäß gebrauchen; Verschlechterungen durch vertragsgemäßen Gebrauch hat er nicht zu vertreten (§ 538).", "Ohne vereinbarten Zweck ist nur die übliche Nutzung gedeckt. Ölverschmutzung durch Autoreparaturen geht darüber hinaus → Verletzung einer Rücksichtnahmepflicht (§ 241 II).", "Martins Irrtum über die Reichweite des Gebrauchs entlastet nicht (Fahrlässigkeit). Schadensersatz neben der Leistung (§ 280 I) ohne Frist; Aufrechnung gegen die Kaution möglich (gleichartige Geldforderungen)."], "o": [null, null, null, null, null, null]}, "a6-50": {"k": "Soweit der Auspuff", "w": ["Unter Privatleuten ist ein Haftungsausschluss wirksam – außer bei Arglist oder Garantie (§ 444). V wusste nichts.", "Mangel? Maßstab ist die übliche Beschaffenheit vergleichbarer Sachen (§ 434 III). Bei 12 Jahren und 102.000 km ist ein durchgerosteter Auspuff typischer Verschleiß → kein Mangel.", "Ohne Mangel auch keine Anfechtung nach § 119 II; diese wäre ohnehin durch das Mängelrecht verdrängt."], "o": [null, null, null, null, null, null]}, "a6-58": {"k": "Die Schadensersatz", "w": ["§ 122 I: Ersatz des Vertrauensschadens bei §§ 118, 119, 120 – verschuldensunabhängig, begrenzt durch das Erfüllungsinteresse.", "Bei § 123 gibt es keinen § 122.", "§ 119 II erfasst Eigenschaften der Person oder Sache, nicht aber den Wert selbst. Die Anfechtung ist empfangsbedürftig (§ 143 I)."], "o": [null, null, null, null, null, null]}, "a6-59": {"k": "Ja, der Rücktritt ", "w": ["Verkauft „als unfallfrei“ → vereinbarte Beschaffenheit; tatsächlich schwerer Unfallschaden → Sachmangel.", "Nacherfüllung unmöglich: Unfallfreiheit lässt sich nicht herstellen, ein vergleichbares Fahrzeug ist nicht zu beschaffen (§ 275 I).", "Rücktritt ohne Frist (§§ 437 Nr. 2, 326 V), verschuldensunabhängig. Mangel erheblich."], "o": [null, null, null, null, null, null]}, "a6-62": {"k": "Bei einer Anfechtu", "w": ["Anfechtungsgrund ist auch ein fahrlässig verursachter Irrtum.", "Nach Anfechtung gemäß §§ 119, 120 ersetzt der Anfechtende den Vertrauensschaden (negatives Interesse), verschuldensunabhängig (§ 122 I).", "Obergrenze ist das positive Interesse. Bei § 123 gibt es keinen Ersatzanspruch. Frist bei Irrtum: unverzüglich (§ 121)."], "o": [null, "§ 122 ist eine verschuldensunabhängige Vertrauenshaftung. Es kommt nur darauf an, dass angefochten wurde und der andere auf die Erklärung vertraut hat.", null, null, null, null]}, "a6-75": {"k": "Ein Kaufvertrag is", "w": ["Inserat „150 € Festpreis“ = invitatio ad offerendum; die Frage nach einer Besichtigung ist noch keine Annahme.", "Katjas „Für 100 € kommen wir ins Geschäft“ = Angebot zu 100 €. Victoria lehnt ab → kein Vertrag.", "Ohne Vertrag gibt es weder Anfechtung noch Mängelrechte (Nacherfüllung, Minderung)."], "o": [null, "Nacherfüllung setzt einen Kaufvertrag voraus. Victoria hat Katjas Angebot abgelehnt, also gibt es keinen.", "Mindern kann nur, wer einen Kaufvertrag hat. Außerdem kannte Katja die Kratzer (§ 442).", null, null, null]}, "a6-77": {"k": "Kassandra muss die", "w": ["Kassandra hebt die Hand bewusst, um zu bieten → Willenserklärung; nach den bekannten Regeln bedeutet sie 120 €. Zuschlag → Vertrag zu 120 € (§ 156).", "Sie meinte 110 € → Inhaltsirrtum über die Bedeutung ihres Zeichens (§ 119 I Alt. 1) → anfechtbar.", "Aber: Die Anfechtung soll nur vor dem Ungewollten schützen. Bietet der andere das Gewollte an (110 €), muss sich die Anfechtende daran festhalten lassen (§ 242)."], "o": [null, null, "Kassandra irrte über die Bedeutung ihres Handhebens (§ 119 I). Sie muss deshalb nicht 120 € zahlen.", null, null, null]}, "PK-34": {"k": "Die Anfechtung nac", "w": ["„Goldkette 585“ ist vereinbarte Beschaffenheit; vergoldetes Silber weicht ab → Sachmangel (§ 434 II).", "Ks Irrtum betrifft genau diese Eigenschaft (§ 119 II). Nach Gefahrübergang haben die Mängelrechte Vorrang – sonst würden Nacherfüllungsvorrang und Verjährung (§ 438) umgangen.", "K muss also über § 437 vorgehen. Eine Anfechtung nach § 123 bliebe möglich, setzt aber Arglist voraus – J wusste nichts."], "o": [null, null, null, null, null, null]}, "PK-4": {"k": "Ein Vertrag über 1", "w": ["B soll nur Ks Erklärung überbringen → Bote, kein Vertreter. Die Erklärung des K geht so zu, wie B sie übermittelt: 100 Kisten.", "H nimmt an → Vertrag über 100 Kisten.", "Unbewusst unrichtige Übermittlung durch einen Boten → K kann wie bei einem Erklärungsirrtum anfechten (§ 120), unverzüglich (§ 121).", "Folge: Vertrauensschaden an H (§ 122)."], "o": [null, null, null, null, null, null]}, "PK-5": {"k": "K kann anfechten; ", "w": ["H droht mit einem empfindlichen Übel (Strafanzeige) → K kauft aus Angst → Drohung (§ 123 I).", "Widerrechtlich: Eine Anzeige ist zwar erlaubt, aber das Mittel hat mit dem Zweck (Oldtimerkauf) nichts zu tun → inadäquate Mittel-Zweck-Relation.", "Frist: 1 Jahr, bei Drohung ab Ende der Zwangslage (§ 124 I, II 1) – hier mit Ks Selbstanzeige. Nach zwei Monaten rechtzeitig.", "§ 121 und § 122 gelten bei § 123 nicht; ein Nachteil ist keine Voraussetzung."], "o": [null, null, null, null, null, null]}, "fb-3-anf1": {"k": "V muss das grüne R", "w": ["Auslegung zuerst (§ 133): Beide wollten übereinstimmend das grüne Rad; „rot“ ist ein Schreibfehler.", "Falsa demonstratio non nocet: Das übereinstimmend Gewollte gilt, auch gegen den Wortlaut der Urkunde.", "Vertrag über das grüne Rad zu 800 €. Ohne Irrtum ist eine Anfechtung weder nötig noch möglich."], "o": [null, null, null, null, null, null]}, "fb-3-anf2": {"k": "M kann nicht anfec", "w": ["M wollte „8.000 €“ erklären und hat das getan → kein Erklärungsirrtum; er wusste auch, was 8.000 € bedeutet → kein Inhaltsirrtum.", "Der Fehler liegt in der internen Vorbereitung → verdeckter Kalkulationsirrtum = Motivirrtum, unbeachtlich.", "Das Kalkulationsrisiko trägt der Kalkulierende (auch kein § 313). Ausnahme allenfalls § 242, wenn K den Fehler erkannt und ausgenutzt hätte – sie kannte die Kalkulation nicht."], "o": [null, null, null, null, null, null]}, "fb-3-anf3": {"k": "V kann nach § 119 ", "w": ["V irrt über die Urheberschaft des Bildes – ein wertbildender Faktor, der der Sache selbst anhaftet → verkehrswesentliche Eigenschaft (§ 119 II). Der Wert selbst wäre keine.", "Der Vorrang des Mängelrechts schützt nur den Verkäufer vor Käufer-Anfechtungen; V als Verkäufer darf anfechten. Sofort → unverzüglich (§ 121).", "Folgen: Vertrag nichtig (§ 142 I), Rückabwicklung nach § 812 (Bild gegen 300 €).", "K erhält den Vertrauensschaden (§ 122): 150 € für Rahmen und Transport – verschuldensunabhängig, nicht das Erfüllungsinteresse."], "o": [null, null, null, null, null, null]}, "fb-3-anf4": {"k": "Rechtzeitig, weil ", "w": ["G sichert Unfallfreiheit wider besseres Wissen zu → arglistige Täuschung (§ 123 I).", "Frist nicht „unverzüglich“ (§ 121 gilt nur für §§ 119, 120), sondern 1 Jahr ab Entdeckung (§ 124 I, II 1).", "Entdeckung am 1. März, Anfechtung am 1. Juni → rechtzeitig. § 122 gilt nicht; die Anfechtung steht selbstständig neben den Mängelrechten."], "o": [null, null, null, null, null, null]}, "fb-3-anf5": {"k": "1, 3 und 5", "w": ["V wollte 510 € schreiben und vertippte sich → Erklärungsirrtum (§ 119 I Alt. 2); unverzüglich angefochten → Vertrag nichtig, kein Lieferanspruch (Aussage 1 richtig, 2 falsch).", "§ 122 I: Vertrauensschaden verschuldensunabhängig (Aussage 4 falsch) – die Fahrkarte von 20 € (Aussage 3).", "Der Ersatz ist durch das Erfüllungsinteresse begrenzt (§ 122 I a. E., Aussage 5).", "Richtig: 1, 3 und 5."], "o": [null, null, null, null, null, null]}, "fb-1-abs1": {"k": "K kann das Geld na", "w": ["Trennungs- und Abstraktionsprinzip: Kaufvertrag und Übereignungen (Uhr, Geld) sind getrennte Geschäfte.", "Ks Eigenschaftsirrtum betrifft nur den Kaufvertrag; bei der Übereignung des Geldes irrte K nicht → keine Fehleridentität.", "Also ist V Eigentümer des Geldes geworden → kein § 985. Der Rechtsgrund ist durch die Anfechtung entfallen (§ 142 I) → § 812 I 1 Alt. 1. Ebenso muss V die Uhr nach § 812 zurückfordern."], "o": [null, null, null, null, null, null]}, "fb-1-abs2": {"k": "R ist Eigentümerin", "w": ["Wucher (§ 138 II): auffälliges Missverhältnis (900 € zu 9.000 €) + Ausbeutung einer Zwangslage (Geld für Operation) → Kaufvertrag nichtig, ohne Anfechtung.", "§ 138 II erfasst ausdrücklich auch das Erfüllungsgeschäft des Bewucherten („sich … gewähren lässt“) → Rs Übereignung ist ebenfalls nichtig.", "R ist Eigentümerin geblieben → § 985. Die 900 € schuldet sie W gesondert aus § 812; § 985 hängt nicht von einer Vorleistung ab."], "o": [null, null, null, null, null, null]}, "fb-6-rm": {"k": "F darf bleiben; K ", "w": ["Kauf bricht nicht Miete (§ 566 I): Der Erwerber tritt in das Mietverhältnis ein → F darf bleiben; die Zusicherung bindet F nicht.", "V hat „bezugsfrei“ zugesichert, das Haus ist aber vermietet → das Mietrecht eines Dritten ist ein Rechtsmangel (§ 435 S. 1).", "Rechtsmängel stehen Sachmängeln gleich → K hat alle Rechte aus § 437 (zuerst Nacherfüllung: Beseitigung des Rechts, dann Rücktritt, Minderung, Schadensersatz)."], "o": [null, null, null, null, null, null]}, "rh6-6": {"k": "Nein, selbst dann ", "w": ["Schweigen ist keine Annahme; der Verlag kann nicht einseitig festlegen, dass Untätigkeit als Zustimmung gilt.", "Zusätzlich § 241a I: Unbestellte Ware eines Unternehmers an einen Verbraucher begründet keine Ansprüche – weder Kaufpreis noch Herausgabe noch Rücksendung.", "Selbst wenn F das Buch verschenkt, schuldet er nichts."], "o": [null, null, null, null, null, null]}, "rh6-9": {"k": "Die WE rückwirkend", "w": ["Anfechtung = einseitiges, empfangsbedürftiges Gestaltungsrecht (§ 143 I), keine Zustimmung nötig.", "Wirkung: Die Willenserklärung ist als von Anfang an nichtig anzusehen (§ 142 I, ex tunc).", "Die Anfechtung vernichtet nur; sie gestaltet den Vertrag nicht um. Verschulden am Irrtum ist unerheblich (Folge: § 122)."], "o": [null, null, null, null, null, null]}, "V-6": {"k": "Es gilt Walfischfl", "w": ["Auslegung vor Anfechtung (§ 133): Beide meinten übereinstimmend Walfischfleisch.", "Falsa demonstratio non nocet: Die gemeinsam falsche Bezeichnung „Haakjöringsköd“ schadet nicht (RG, Haakjöringsköd-Fall).", "Vertrag über Walfischfleisch; V hat ordnungsgemäß geliefert. Kein Dissens, kein Irrtum; der Preisverfall ist ein unbeachtlicher Motivirrtum."], "o": [null, null, null, null, null, null]}, "V-7": {"k": "80 € Transport + 3", "w": ["M hat wegen Erklärungsirrtums wirksam angefochten → § 122 I: Vertrauensschaden, verschuldensunabhängig.", "Vertrauensschaden: K hätte ohne Ms Erklärung das Angebot zu 2.300 € angenommen; jetzt kostet der Schrank 2.600 € → 300 €. Dazu Transporter 80 € → 380 €.", "Obergrenze Erfüllungsinteresse: Marktpreis 2.600 € − Vertragspreis 1.900 € = 700 €. 380 € liegen darunter.", "§ 122 II greift nicht: 1.900 € statt 2.900 € ist nicht offensichtlich falsch."], "o": [null, null, null, null, null, null]}, "V-8": {"k": "Nein, ein interner", "w": ["B wollte 48.000 € erklären und hat das getan → kein Erklärungs-, kein Inhaltsirrtum.", "Vergessene Fliesenarbeiten in der internen Kalkulation = verdeckter Kalkulationsirrtum → Motivirrtum, unbeachtlich.", "Ohne Anfechtungsgrund hilft auch eine unverzügliche Erklärung nicht. Das Risiko interner Rechenfehler trägt B."], "o": [null, null, null, null, null, null]}, "fb-2-zug2": {"k": "Der Vertrag ist zu", "w": ["Zugang des Angebots (§ 130 I 1): Einwurf um 10 Uhr in den privaten Briefkasten → Leerung noch am selben Tag zu erwarten → Zugang am Dienstag (spätestens nachmittags).", "Widerruf um 18 Uhr: wirkt nur, wenn er vorher oder gleichzeitig zugeht (§ 130 I 2) → zu spät.", "A ist gebunden (§ 145); Bs Annahme am Mittwoch schließt den Vertrag. Reue ist kein Irrtum; § 355 gilt hier nicht."], "o": [null, null, null, null, null, null]}, "fb-2-form2": {"k": "Nein. Der Formmang", "w": ["Schenkungsversprechen bedarf notarieller Beurkundung (§ 518 I); Zeugen ersetzen sie nicht → zunächst formnichtig (§ 125).", "Heilung (§ 518 II): Mit der Überweisung ist die Leistung bewirkt → Schenkung wirksam → Rechtsgrund, kein § 812.", "Rückforderung nur bei Widerruf wegen groben Undanks (§ 530) – ein Streit ist keine schwere Verfehlung."], "o": [null, null, null, null, null, null]}, "fb-2-vs1": {"k": "Kein Vertrag, weil", "w": ["Shop-Darstellung = invitatio ad offerendum; Ks Bestellung = Angebot.", "Die automatische E-Mail bestätigt nur den Eingang und kündigt eine Prüfung an (§ 312i I 1 Nr. 3) → keine Annahme, auch nicht teilweise.", "U lehnt am nächsten Tag ab → kein Vertrag; eine Anfechtung ist nicht nötig."], "o": [null, null, null, null, null, null]}, "fb-9-812b": {"k": "Ja, aus § 812 I 1 ", "w": ["K zahlte 400 € mehr als geschuldet → Leistung ohne Rechtsgrund → § 812 I 1 Alt. 1.", "§ 814 schließt die Rückforderung aus, wenn der Leistende wusste, dass er nicht schuldet. Zweck: Wer wissentlich zahlt, verhält sich widersprüchlich, wenn er zurückfordert.", "Kein Widerspruch, wenn unter ausdrücklichem Vorbehalt oder unter Druck (Auto wird sonst nicht herausgegeben) gezahlt wird → § 814 greift nicht. Eine Anfechtung der Zahlung ist nicht nötig."], "o": [null, null, null, null, null, null]}, "fb-5-323iv": {"k": "Ja, schon vor Fäll", "w": ["Rücktritt wegen Nichtleistung (§ 323 I) setzt grundsätzlich Fälligkeit und Fristablauf voraus.", "§ 323 IV: Rücktritt schon vor Fälligkeit, wenn offensichtlich ist, dass die Voraussetzungen eintreten werden.", "§ 323 II Nr. 1: Frist entbehrlich bei ernsthafter und endgültiger Erfüllungsverweigerung – „keinesfalls liefern“.", "H kann im Oktober zurücktreten, verschuldensunabhängig; Schadensersatz für M gibt es nicht."], "o": [null, null, null, null, null, null]}, "P2-frist-10": {"k": "Am Montag, 2. 3. 2", "w": ["Zugang Sa 31.1. = Ereignis → Ereignistag zählt nicht (§ 187 I).", "Monatsfrist endet mit dem Tag des Folgemonats, der dieselbe Zahl trägt (§ 188 II). Einen 31.2. gibt es nicht → letzter Tag des Monats, Sa 28.2. (§ 188 III).", "Fällt das Ende auf einen Samstag, Sonntag oder Feiertag, tritt der nächste Werktag an seine Stelle (§ 193) → Mo 2.3.2026."], "o": [null, null, null, null, null, null]}, "P2-frist-11": {"k": "Am Mittwoch, 11. 1", "w": ["Zugang Mi 4.11. = Ereignis → Tag zählt nicht (§ 187 I).", "Wochenfrist endet mit dem gleich benannten Wochentag der Folgewoche (§ 188 II) → Mi 11.11.", "Fristen enden mit Ablauf des Tages, also um 24 Uhr; es zählen Kalendertage."], "o": [null, null, null, null, null, null]}, "P2-frist-12": {"k": "Nicht verjährt; K ", "w": ["Mängelansprüche verjähren in 2 Jahren ab Ablieferung (§ 438 I Nr. 3, II) – nicht ab Entdeckung, nicht ab Jahresende.", "Übergabe 10.3.2024 → Verjährung mit Ablauf des 10.3.2026. Am 2.3.2026 noch nicht verjährt.", "Beweislast: Die Vermutung, dass der Mangel schon bei Übergabe vorlag, gilt nur 1 Jahr (§ 477 I). Danach muss K beweisen."], "o": [null, null, null, null, null, null]}, "P2-frist-13": {"k": "Die Forderung ist ", "w": ["Werklohn → regelmäßige Verjährung 3 Jahre (§ 195).", "Beginn mit Schluss des Jahres, in dem der Anspruch entstanden ist und der Gläubiger Kenntnis hat (§ 199 I) → 31.12.2023.", "Ende mit Ablauf des 31.12.2026 → Klage am 15.11.2026 rechtzeitig. Mahnungen ändern daran nichts."], "o": [null, null, null, null, null, null]}, "fb-3-vj2": {"k": "Nicht verjährt; di", "w": ["Regelverjährung: Beginn 31.12.2022 (§ 199 I), Ende eigentlich 31.12.2025.", "Im November 2025 erkennt K die Forderung an – ausdrücklich und durch Abschlagszahlung (§ 212 I Nr. 1). Das Anerkenntnis ist formfrei und erfasst die ganze Forderung.", "Folge: Neubeginn – taggenau ab November 2025, ohne Jahresendregel → Ende November 2028. Klage im März 2027 rechtzeitig."], "o": [null, null, null, null, null, null]}, "V-10": {"k": "V kann trotz Verjä", "w": ["Kaufpreisforderung verjährt → K hat ein Leistungsverweigerungsrecht (§ 214 I). Ein Rücktritt wegen der Nichtzahlung wäre deshalb grundsätzlich unwirksam (§ 218 I).", "Ausnahme § 216 II 2: Bei Eigentumsvorbehalt kann der Verkäufer trotzdem zurücktreten – sonst wäre seine Sicherheit wertlos. Dann kann er die Maschine herausverlangen (§§ 449 II, 985, 346).", "Rücktritt → Rückgewährschuldverhältnis (§§ 346 ff.): K gibt die Maschine zurück und schuldet Ersatz für Nutzungen; V erstattet die Raten, Zug um Zug (§ 348).", "Das Rücktrittsrecht selbst verjährt nicht – Gestaltungsrechte unterliegen keiner Verjährung (§ 194 I)."], "o": [null, null, null, null, null, null]}, "rh6-40": {"k": "Freitag, 14. Juli ", "w": ["Eingang der Bestellung im Lauf des Tages = Ereignis → der 7.7. zählt nicht (§ 187 I).", "Tagesfrist von 7 Tagen: 8.7. bis 14.7. (§ 188 I).", "Fr 14.7. ist ein Werktag → § 193 greift nicht. Spätester Liefertag: Freitag, 14. Juli 2023."], "o": [null, null, null, null, null, null]}, "h15": {"k": "Nein: Die Teilzahl", "w": ["Regelverjährung: entstanden 2021 → Beginn 31.12.2021, Ende eigentlich 31.12.2024.", "Teilzahlung „als erste Rate“ am 10.2.2023 = Anerkenntnis (§ 212 I Nr. 1) → Neubeginn taggenau → neue Frist bis 10.2.2026.", "Klage am 20.12.2025 hemmt (§ 204 I Nr. 1). Die Zustellung im Januar 2026 erfolgt „demnächst“ und wirkt auf die Einreichung zurück (§ 167 ZPO).", "Nicht verjährt. § 634a gilt nur für Mängelansprüche des Bestellers, nicht für den Werklohn."], "o": [null, null, null, null, null, null]}, "W-17": {"k": "Am 22.4. um 24 Uhr", "w": ["Eine Mahnung wird mit Zugang wirksam → maßgeblich ist der 12.4., nicht das Datum des Schreibens.", "Zugang = Ereignis → der 12.4. zählt nicht (§ 187 I). Fristbeginn 13.4.", "10 Tage → Ende mit Ablauf des 22.4. (§ 188 I). Der 22.4. ist ein Werktag → keine Verschiebung nach § 193."], "o": [null, null, null, null, null, null]}, "W-18": {"k": "Am 31.12.2026 um 2", "w": ["Lieferung und Kaufpreis sind Erfüllungsansprüche → regelmäßige Verjährung 3 Jahre (§ 195); § 438 gilt nur für Mängelansprüche.", "Beginn: Schluss des Jahres der Entstehung und Kenntnis (§ 199 I) → 31.12.2023, 24 Uhr.", "Ende: Ablauf des 31.12.2026 (Ultimo-Verjährung)."], "o": [null, null, null, null, null, null]}, "L2-13": {"k": "Mit Ablauf des 31.", "w": ["Kaufpreisanspruch → regelmäßige Verjährung 3 Jahre (§ 195), nicht § 438.", "Entstanden und bekannt 2024 → Beginn 31.12.2024 (§ 199 I) → Ende 31.12.2027.", "Mahnungen bewirken weder Hemmung noch Neubeginn (§ 212 verlangt Anerkenntnis oder Vollstreckungshandlung).", "Klage im Januar 2028 zu spät → K kann die Einrede erheben (§ 214 I)."], "o": [null, null, null, null, null, null]}, "L2-14": {"k": "Am Dienstag, 11. M", "w": ["Fristauslösendes Ereignis ist der Zugang (Di 4.3.), nicht das Datum des Schreibens. Der Ereignistag zählt nicht (§ 187 I).", "Wochenfrist endet am gleich benannten Wochentag der Folgewoche (§ 188 II) → Di 11.3., 24 Uhr.", "Gerechnet wird in ganzen Tagen, nicht stundengenau → Reparatur am 11.3. um 18 Uhr rechtzeitig."], "o": [null, null, null, null, null, null]}, "L2-15": {"k": "Ja: Endet die Fris", "w": ["§ 193: Fällt das Ende einer Frist auf einen Sonntag, Feiertag oder Sonnabend (Samstag), tritt der nächste Werktag an seine Stelle.", "Gilt für alle Fristen, auch vertraglich oder einseitig gesetzte (§ 186), und unabhängig von Verbrauchereigenschaft.", "Ende also Mo 5.5., 24 Uhr → Mitteilung um 10 Uhr rechtzeitig. Der Montag ist selbst der letzte Tag."], "o": [null, null, null, null, null, null]}, "L2-16": {"k": "Nein: Was auf eine", "w": ["Verjährung lässt die Forderung bestehen; der Schuldner kann nur die Leistung verweigern (§ 214 I).", "Zahlt er trotzdem, hat der Gläubiger mit Rechtsgrund empfangen → kein § 812.", "§ 214 II stellt klar: Das Geleistete kann nicht zurückgefordert werden, auch wenn in Unkenntnis der Verjährung gezahlt wurde. Ein Irrtum darüber ist ein unbeachtlicher Rechtsfolgenirrtum."], "o": [null, null, null, null, null, null]}, "L2-17": {"k": "Nein: Das Anerkenn", "w": ["Ursprünglich: Beginn 31.12.2022, Ende 31.12.2025.", "Brief vom 10.3.2025: „Ich weiß, dass ich schulde … bitte um Stundung“ = Anerkenntnis (§ 212 I Nr. 1), formfrei.", "Neubeginn taggenau ab 10.3.2025 → neue Frist bis 10.3.2028. Klage im Februar 2027 rechtzeitig. § 205 greift nicht, weil keine Stundung gewährt wurde."], "o": [null, null, null, null, null, null]}, "PK-20": {"k": "Frühestens mit Abl", "w": ["Verhandlungen über den Anspruch hemmen die Verjährung (§ 203 S. 1): Die Zeit vom 1.12. bis 20.12. wird nicht eingerechnet (§ 209).", "Zusätzlich Ablaufhemmung (§ 203 S. 2): Die Verjährung tritt frühestens 3 Monate nach dem Ende der Hemmung ein.", "Ende der Verhandlungen 20.12.2025 → frühestens mit Ablauf des 20.3.2026."], "o": [null, null, null, null, null, null]}, "PK-21": {"k": "Bis Montag, 02.03.", "w": ["Zugang Sa 31.1. = Ereignis, zählt nicht (§ 187 I).", "Monatsfrist: Ende am Tag mit gleicher Zahl im Folgemonat (§ 188 II); fehlt der 31.2. → letzter Februartag, Sa 28.2. (§ 188 III).", "Samstag → § 193 verschiebt auf den nächsten Werktag, Mo 2.3.2026. § 193 gilt auch für gesetzte Fristen."], "o": [null, null, null, null, null, null]}, "V-9": {"k": "Nein, die Frist li", "w": ["Schadensersatz aus § 823 I → regelmäßige Verjährung 3 Jahre (§ 195).", "Beginn: Schluss des Jahres, in dem der Anspruch entstand und B Kenntnis von Schaden und Schädiger erlangte (§ 199 I) → beides 2024 → 31.12.2024. Ende 31.12.2027.", "Mahnungen bewirken keinen Neubeginn. Die Klage am 15.12.2027 hemmt (§ 204 I Nr. 1); Zustellung „demnächst“ wirkt zurück (§ 167 ZPO) → nicht verjährt."], "o": [null, null, null, null, null, null]}, "fb-2-zug1": {"k": "Kein Vertrag: Die ", "w": ["Angebot mit Frist bis Samstag 24 Uhr (§ 148) → die Annahme muss bis dahin zugehen.", "Zugang (§ 130 I 1): Einwurf am Samstag um 19 Uhr bei geschlossenem Betrieb → mit Kenntnisnahme ist erst Montag zu rechnen → verspätet.", "Verspätete Annahme gilt als neues Angebot (§ 150 I), das D ablehnen darf. § 149 hilft nicht – es gab keine Beförderungsstörung."], "o": [null, null, null, null, null, null]}});
